// clipFrame cuts a rendered frame to at most rows lines of at most cols cells, by the
// cluster measure the width check uses (celltext; ansi.Truncate under-counts keycaps).
func clipFrame(frame string, cols, rows int) string {
	lines := strings.Split(frame, "\n")
	if len(lines) > rows {
		lines = lines[:max(rows, 0)]
	}
	for i, l := range lines {
		if ansi.StringWidth(l) > cols {
			lines[i] = celltext.ClipANSI(l, cols)
		}
	}
	return strings.Join(lines, "\n")
}
